    const commits = list.filter((x) => x && x.kind === 'showSettings-post-commit');
    const last = commits.length ? commits[commits.length - 1] : null;
    const lastVal = last && typeof last.value === 'boolean' ? last.value : null;
    if (has('close-settings-invoke') && lastVal === false) {
