const OFFLINE_KILL_PRECLICK_SNAPSHOT_BUDGET_MS = 2000;

/**
 * Bounded preclick DOM snapshot for offline-kill diagnostics. Never blocks the opener click path
 * beyond {@link OFFLINE_KILL_PRECLICK_SNAPSHOT_BUDGET_MS}.
 */
async function collectOfflineKillOpenSettingsPreclickStateSafe(pg, extra = {}, hook = {}) {
    const pushStage = typeof hook.pushStage === 'function' ? hook.pushStage : () => {};
    const timeoutRaw = extra.preclickSnapshotTimeoutMs;
    const timeoutMs =
        typeof timeoutRaw === 'number' && Number.isFinite(timeoutRaw)
            ? Math.max(200, Math.floor(timeoutRaw))
            : OFFLINE_KILL_PRECLICK_SNAPSHOT_BUDGET_MS;
    const raceExtra = { ...extra };
    delete raceExtra.preclickSnapshotTimeoutMs;
    pushStage('early-open-settings-stage-preclick-snapshot-evaluate-start');
    let result;
    try {
        result = await Promise.race([
            collectOfflineKillOpenSettingsPreclickState(pg, raceExtra).then((payload) => ({ ok: true, payload })),
            new Promise((resolve) => {
                setTimeout(() => resolve({ ok: false, timedOut: true }), timeoutMs);
            }),
        ]);
    } catch (err) {
        pushStage('early-open-settings-stage-preclick-snapshot-error');
        const msg = err && err.message ? String(err.message) : String(err);
        return {
            captureOk: false,
            preclickSnapshotTimedOut: false,
            preclickSnapshotError: msg,
            preclickSnapshotPartial: true,
            continuedAfterPreclickSnapshotFailure: true,
            preclickSnapshotBudgetMs: timeoutMs,
            timestamp: new Date().toISOString(),
            pageClosed: pg.isClosed(),
            budgetRemainingMsApprox:
                typeof raceExtra.budgetRemainingMsApprox === 'number' ? raceExtra.budgetRemainingMsApprox : null,
            settingsOpenButtonCount: -1,
            collectError: msg,
            chosenLocatorDescription:
                typeof raceExtra.chosenLocatorDescription === 'string' ? raceExtra.chosenLocatorDescription : '',
            chosenCandidateIndex:
                typeof raceExtra.chosenCandidateIndex === 'number' ? raceExtra.chosenCandidateIndex : null,
        };
    }
    if (!result.ok && result.timedOut) {
        pushStage('early-open-settings-stage-preclick-snapshot-timeout');
        return {
            captureOk: false,
            preclickSnapshotTimedOut: true,
            preclickSnapshotPartial: true,
            continuedAfterPreclickSnapshotFailure: true,
            collectError: `preclick snapshot exceeded ${timeoutMs}ms`,
            preclickSnapshotBudgetMs: timeoutMs,
            timestamp: new Date().toISOString(),
            pageClosed: pg.isClosed(),
            budgetRemainingMsApprox:
                typeof raceExtra.budgetRemainingMsApprox === 'number' ? raceExtra.budgetRemainingMsApprox : null,
            settingsOpenButtonCount: -1,
            chosenLocatorDescription:
                typeof raceExtra.chosenLocatorDescription === 'string' ? raceExtra.chosenLocatorDescription : '',
            chosenCandidateIndex:
                typeof raceExtra.chosenCandidateIndex === 'number' ? raceExtra.chosenCandidateIndex : null,
        };
    }
    const payload = result.payload;
    pushStage('early-open-settings-stage-preclick-snapshot-evaluate-done');
    pushStage('early-open-settings-stage-preclick-snapshot-candidates-start');
    pushStage('early-open-settings-stage-preclick-snapshot-candidates-done');
    const innerErr = payload && payload.collectError ? String(payload.collectError) : '';
    return {
        ...payload,
        captureOk: true,
        preclickSnapshotTimedOut: false,
        preclickSnapshotPartial: Boolean(innerErr),
        continuedAfterPreclickSnapshotFailure: Boolean(innerErr),
        preclickSnapshotBudgetMs: timeoutMs,
    };
}

