function classifyOfflineKillProviderVisibleEnabledTimeout(s) {
    const st = s && typeof s === 'object' ? s : {};
    if (st.pageClosed) return 'offline-kill-provider-visible-page-closed';
    if (!st.settingsDrawerPresent) return 'offline-kill-provider-visible-drawer-missing';
    if (st.loadingShellPresent) return 'offline-kill-provider-visible-drawer-loading';
    if (!st.settingsDrawerVisible) return 'offline-kill-provider-visible-drawer-loading';
    if (st.settingsDrawerReady === false || st.settingsDrawerDataReady === 'false') {
        return 'offline-kill-provider-visible-drawer-loading';
    }
    if (!st.connectionPanelPresent) return 'offline-kill-provider-visible-connection-panel-missing';
    if (!st.connectionPanelVisible) return 'offline-kill-provider-visible-connection-panel-hidden';
    const tab = String(st.activeSettingsTab || 'unknown');
    if (tab !== 'connection' && tab !== 'unknown') {
        return 'offline-kill-provider-visible-wrong-settings-tab';
    }
    const n = Number(st.providerControlCount);
    if (!Number.isFinite(n) || n <= 0) return 'offline-kill-provider-visible-provider-control-missing';
    if (!st.providerControlVisible) return 'offline-kill-provider-visible-provider-control-hidden';
    if (
        st.providerControlEnabled === false ||
        st.providerControlDisabledAttr === true ||
        st.providerControlAriaDisabled === 'true'
    ) {
        return 'offline-kill-provider-visible-provider-control-disabled';
    }
    return 'offline-kill-provider-visible-unknown-timeout';
}

async function collectOfflineKillProviderVisibleEnabledTimeoutStateBestEffort(pg = page) {
    if (pg.isClosed()) {
        return { pageClosed: true, collectError: 'page-closed' };
    }
    try {
        return await pg.evaluate(() => {
            const rectVis = (el) => {
                if (!el) return { present: false, visible: false, rect: null };
                const r = el.getBoundingClientRect();
                const st = window.getComputedStyle(el);
                const vis =
                    r.width > 0 &&
                    r.height > 0 &&
                    st.display !== 'none' &&
                    st.visibility !== 'hidden' &&
                    Number(st.opacity || '1') > 0;
                return {
                    present: true,
                    visible: vis,
                    rect: {
                        x: Math.round(r.x),
                        y: Math.round(r.y),
                        width: Math.round(r.width),
                        height: Math.round(r.height),
                    },
                };
            };

            const drawers = Array.from(document.querySelectorAll('[data-testid="settings-drawer"]'));
            const openDrawer =
                drawers.find((d) => d.getAttribute('data-state') === 'open') || drawers[0] || null;
            const drawerVis = rectVis(openDrawer);
            const dr = openDrawer ? openDrawer.getAttribute('data-ready') : null;

            const loadingShell = document.querySelector('[data-testid="settings-drawer-loading"]');
            const loadingVis = rectVis(loadingShell);

            const connPanel = document.querySelector('[data-testid="settings-panel-connection"]');
            const connVis = rectVis(connPanel);

            const tabs = Array.from(document.querySelectorAll('[data-testid^="settings-tab-"]'));
            const activeTabEl = tabs.find((t) => t.getAttribute('data-active') === 'true') || null;
            const activeTid = activeTabEl ? activeTabEl.getAttribute('data-testid') || '' : '';
            const activeSettingsTab = activeTid.startsWith('settings-tab-')
                ? activeTid.slice('settings-tab-'.length)
                : 'unknown';

            const controls = document.querySelector('[data-testid="settings-connection-controls"]');
            const scope = controls || document;
            const selects = Array.from(scope.querySelectorAll('[data-testid="settings-provider-select"]'));
            const first = selects[0] || null;
            const pv = rectVis(first);
            const selectedProvider = first
                ? (first instanceof HTMLSelectElement ? first.value : first.textContent || '').trim().slice(
                      0,
                      200,
                  )
                : '';

            const compact = (() => {
                try {
                    const body = document.body;
                    if (!body) return { bodyChildren: 0, sampleTestIds: [] };
                    const walk = [];
                    const stack = [body];
                    let steps = 0;
                    while (stack.length && steps < 800) {
                        steps += 1;
                        const n = stack.pop();
                        if (!n || n.nodeType !== 1) continue;
                        const tid = n.getAttribute && n.getAttribute('data-testid');
                        if (tid && /^settings-|^offline-kill-|^shell-/.test(tid)) {
                            walk.push(tid);
                            if (walk.length >= 40) break;
                        }
                        const ch = n.children || [];
                        for (let i = ch.length - 1; i >= 0; i -= 1) stack.push(ch[i]);
                    }
                    return { bodyChildren: body.children ? body.children.length : 0, sampleTestIds: walk };
                } catch (e) {
                    return { bodyChildren: -1, sampleTestIds: [], compactError: e.message || String(e) };
                }
            })();

            return {
                pageClosed: false,
                settingsDrawerPresent: Boolean(openDrawer),
                settingsDrawerVisible: drawerVis.visible,
                settingsDrawerReady: dr === 'true',
                settingsDrawerDataReady: dr,
                loadingShellPresent: loadingVis.present && loadingVis.visible,
                connectionPanelPresent: connVis.present,
                connectionPanelVisible: connVis.visible,
                activeSettingsTab,
                providerControlCount: selects.length,
                providerControlVisible: pv.visible,
                providerControlEnabled: first ? !first.disabled : false,
                providerControlDisabledAttr: first ? first.hasAttribute('disabled') : false,
                providerControlAriaDisabled: first ? first.getAttribute('aria-disabled') : null,
                providerControlBoundingBox: pv.rect,
                providerControlText: first
                    ? (first instanceof HTMLSelectElement
                          ? Array.from(first.selectedOptions || [])
