                drawers.find((d) => d.getAttribute('data-state') === 'open') || drawers[0] || null;
            const drawerVis = rectVis(openDrawer);
            const dr = openDrawer ? openDrawer.getAttribute('data-ready') : null;

            const loadingShell = document.querySelector('[data-testid="settings-drawer-loading"]');
            const loadingVis = rectVis(loadingShell);

            const connPanel = document.querySelector('[data-testid="settings-panel-connection"]');
            const connVis = rectVis(connPanel);

            const tabs = Array.from(document.querySelectorAll('[data-testid^="settings-tab-"]'));
            const activeTabEl = tabs.find((t) => t.getAttribute('data-active') === 'true') || null;
            const activeTid = activeTabEl ? activeTabEl.getAttribute('data-testid') || '' : '';
            const activeSettingsTab = activeTid.startsWith('settings-tab-')
                ? activeTid.slice('settings-tab-'.length)
                : 'unknown';

            const controls = document.querySelector('[data-testid="settings-connection-controls"]');
            const scope = controls || document;
            const selects = Array.from(scope.querySelectorAll('[data-testid="settings-provider-select"]'));
            const first = selects[0] || null;
            const pv = rectVis(first);
            const providerControlTagName = first ? String(first.tagName || '').toLowerCase() : '';
            const providerControlRole = first ? first.getAttribute('role') || '' : '';
            const selectedProvider = first
                ? (first instanceof HTMLSelectElement ? first.value : first.textContent || '').trim().slice(
                      0,
                      200,
                  )
                : '';
            const providerControlText = first
                ? (first instanceof HTMLSelectElement
                      ? Array.from(first.selectedOptions || [])
                            .map((o) => (o.textContent || '').trim())
                            .join(' | ')
                            .slice(0, 300)
                      : (first.textContent || '').trim().slice(0, 300))
                : '';
            const providerControlValue = first && first instanceof HTMLSelectElement ? String(first.value || '') : '';

            let openrouterOptionPresent = false;
            let openrouterOptionVisible = false;
            let openrouterOptionEnabled = false;
            let orOpt = null;
            if (first instanceof HTMLSelectElement) {
                orOpt = Array.from(first.options).find((o) => String(o.value) === 'openrouter') || null;
                if (orOpt) {
                    openrouterOptionPresent = true;
                    const ov = rectVis(orOpt);
                    openrouterOptionVisible = ov.visible;
                    openrouterOptionEnabled = !orOpt.disabled;
                }
            }

            const providerOptions =
                first instanceof HTMLSelectElement
                    ? Array.from(first.options)
                          .slice(0, 48)
                          .map((o) => ({
                              value: String(o.value || ''),
                              text: (o.textContent || '').trim().slice(0, 120),
                              disabled: Boolean(o.disabled),
                          }))
                    : [];

            let providerDropdownOpen = false;
            if (first) {
                if (first.getAttribute('aria-expanded') === 'true') providerDropdownOpen = true;
                let p = first.parentElement;
                for (let i = 0; i < 14 && p; i += 1) {
                    if (p.getAttribute && p.getAttribute('aria-expanded') === 'true') {
                        providerDropdownOpen = true;
                        break;
                    }
                    p = p.parentElement;
                }
            }

            return {
                pageClosed: false,
                settingsDrawerPresent: Boolean(openDrawer),
                settingsDrawerVisible: drawerVis.visible,
                settingsDrawerReady: dr === 'true',
                drawerDataReady: dr,
                loadingShellPresent: loadingVis.present && loadingVis.visible,
                activeSettingsTab,
                connectionPanelPresent: connVis.present,
                connectionPanelVisible: connVis.visible,
                providerControlPresent: Boolean(first),
                providerControlVisible: pv.visible,
                providerControlEnabled: first ? !first.disabled : false,
                providerControlDisabledAttr: first ? first.hasAttribute('disabled') : false,
                providerControlAriaDisabled: first ? first.getAttribute('aria-disabled') : null,
                providerControlTagName,
                providerControlRole,
                providerControlText,
                providerControlValue,
                selectedProvider,
                openrouterOptionPresent,
                openrouterOptionVisible,
                openrouterOptionEnabled,
                providerOptions,
                providerDropdownOpen,
                documentReadyState: document.readyState,
                pageUrl: location.href,
            };
        });
    } catch (err) {
        return {
            pageClosed: pg.isClosed(),
            collectError: err && err.message ? err.message : String(err),
        };
    }
}

