# Staged + single zip upload: hundreds of small JSON files caused ENOBUFS on CreateArtifact (25772166500,
# 25774759074). Default bundle skips video/screenshots/large JSON unless critical path match; trace.zip
# only when UPLOAD_HEAVY_VERIFY_UI_DIAGNOSTICS=true (repo/org variable).
- name: Bundle and archive minimal Verify UI diagnostics
  if: always()
  shell: pwsh
  run: |
    $ErrorActionPreference = "Stop"
    $heavy = ($env:UPLOAD_HEAVY_VERIFY_UI_DIAGNOSTICS -eq "true")
    Write-Host "UPLOAD_HEAVY_VERIFY_UI_DIAGNOSTICS=$($env:UPLOAD_HEAVY_VERIFY_UI_DIAGNOSTICS) (heavy=$heavy)"

    $staging = "verify-ui-artifact-staging"
    if (Test-Path -LiteralPath $staging) { Remove-Item -LiteralPath $staging -Recurse -Force }
    New-Item -ItemType Directory -Force -Path $staging | Out-Null
    "verify-ui minimal staging at $(Get-Date -Format o) heavy=$heavy" | Out-File -Encoding utf8 (Join-Path $staging "verify-ui-minimal-marker.txt")

    $criticalJsonRegex = [regex]::new(
      "(offline-kill|open-settings|timeout|provider-select|ensure-panel|force-posture|verify-ui|state-gate|handler-trace|first-click|opener-binding|classification|settings-open|mounted-drawer|runtime-state|preclick|postclick|react-core|agentInstall|provGraph|voiceRoom)",
      [System.Text.RegularExpressions.RegexOptions]::IgnoreCase
    )
    $maxJsonIncludeBytesDefault = 180kb
    $maxJsonIncludeBytesHeavy = 12mb
    $maxJsonIncludeBytes = $(if ($heavy) { $maxJsonIncludeBytesHeavy } else { $maxJsonIncludeBytesDefault })
    $maxSingleFileBytes = $(if ($heavy) { 80mb } else { 6mb })
    $skipped = [System.Collections.Generic.List[string]]::new()
    $included = 0

    function Should-IncludeFile {
      param([System.IO.FileInfo]$f, [string]$rel)
      $ext = $f.Extension.ToLowerInvariant()
      $len = $f.Length
      $relL = $rel.ToLowerInvariant()

      if ($ext -in @(".webm", ".mp4", ".png", ".jpg", ".jpeg", ".gif", ".bmp", ".ico")) { return $false }
      if ($ext -eq ".zip") {
        if ($heavy -and ($f.Name -ieq "trace.zip")) { return ($len -le $maxSingleFileBytes) }
        return $false
      }
      if ($ext -in @(".md", ".txt")) { return ($len -le $maxSingleFileBytes) }
      if ($ext -eq ".json") {
        if ($len -gt $maxSingleFileBytes) { return $false }
        if ($len -le $maxJsonIncludeBytes) { return $true }
        if ($criticalJsonRegex.IsMatch($rel)) { return $true }
        return $false
      }
      return $false
    }

    if (Test-Path -LiteralPath "test-results") {
      $base = (Resolve-Path -LiteralPath "test-results").Path
      Get-ChildItem -LiteralPath "test-results" -Recurse -File | ForEach-Object {
        $rel = [System.IO.Path]::GetRelativePath($base, $_.FullName)
        if (-not (Should-IncludeFile $_ $rel)) {
          if ($_.Length -gt 65536) { $skipped.Add("$rel ($($_.Length) bytes)") | Out-Null }
          return
        }
        $dest = Join-Path $staging "test-results" $rel
        New-Item -ItemType Directory -Force -Path (Split-Path -Parent $dest) | Out-Null
        Copy-Item -LiteralPath $_.FullName -Destination $dest -Force
        $script:included++
      }
    }

    # Optional: tiny Playwright HTML report summary (skip entire tree — heavy).
    $prData = Join-Path "playwright-report" "data"
    if ((Test-Path -LiteralPath $prData) -and -not $heavy) {
      Get-ChildItem -LiteralPath $prData -Recurse -File -Filter "*.md" -ErrorAction SilentlyContinue | ForEach-Object {
        if ($_.Length -le 512kb) {
          $dest = Join-Path $staging "playwright-report" ([System.IO.Path]::GetRelativePath((Resolve-Path "playwright-report").Path, $_.FullName))
          New-Item -ItemType Directory -Force -Path (Split-Path -Parent $dest) | Out-Null
          Copy-Item -LiteralPath $_.FullName -Destination $dest -Force
          $script:included++
        }
      }
    }

    Write-Host "verify-ui-bundle-files-included=$included"
    Write-Host "verify-ui-bundle-files-skipped-large_or_filtered=$($skipped.Count)"

    $files = @(Get-ChildItem -LiteralPath $staging -Recurse -File -ErrorAction SilentlyContinue)
    $count = $files.Count
    $sum = ($files | Measure-Object -Property Length -Sum).Sum
    if (-not $sum) { $sum = 0 }
    Write-Host "verify-ui-artifact-file-count=$count"
    Write-Host "verify-ui-artifact-total-bytes=$sum"
    $top = $files | Sort-Object Length -Descending | Select-Object -First 25
    foreach ($t in $top) {
      $r = $t.FullName.Substring((Resolve-Path $staging).Path.Length).TrimStart("\", "/")
      Write-Host "verify-ui-artifact-largest-files=$r|$($t.Length)"
    }

    $zipPath = Join-Path (Get-Location) "verify-ui-minimal.zip"
    if (Test-Path -LiteralPath $zipPath) { Remove-Item -LiteralPath $zipPath -Force }
    if ($count -eq 0) {
      "empty staging — marker only" | Out-File -Encoding utf8 (Join-Path $staging "verify-ui-empty.txt")
      $files = @(Get-ChildItem -LiteralPath $staging -Recurse -File)
      $count = $files.Count
      $sum = ($files | Measure-Object -Property Length -Sum).Sum
      Write-Host "verify-ui-artifact-file-count(after-empty-marker)=$count"
      Write-Host "verify-ui-artifact-total-bytes=$sum"
    }
    Compress-Archive -Path (Join-Path $staging "*") -DestinationPath $zipPath -Force
    $zipItem = Get-Item -LiteralPath $zipPath
    Write-Host "verify-ui-minimal-zip-bytes=$($zipItem.Length)"
    Write-Host "verify-ui-minimal-zip-path=$($zipItem.FullName)"

