# Bounded Playwright serial E2E for Verify UI (GitHub Actions Windows).
# Exits with a non-zero code on timeout so the job can conclude as failure instead of hanging until cancelled.
$ErrorActionPreference = "Continue"

$repoRoot = if ($env:GITHUB_WORKSPACE) { $env:GITHUB_WORKSPACE } else { (Resolve-Path (Join-Path $PSScriptRoot "..")).Path }
Set-Location $repoRoot

$stdoutLog = Join-Path $repoRoot "verify-ui-serial-worker.stdout.log"
$stderrLog = Join-Path $repoRoot "verify-ui-serial-worker.stderr.log"
Remove-Item $stdoutLog, $stderrLog -ErrorAction SilentlyContinue

$timeoutMs = 75 * 60 * 1000
if ($env:VERIFY_UI_SERIAL_TIMEOUT_MS -match '^\d+$') {
  $timeoutMs = [int]$env:VERIFY_UI_SERIAL_TIMEOUT_MS
}

function Write-Diagnostics {
  param([string]$Reason)
  Write-Host "verify-ui-serial-worker-diagnostics=$Reason"
  Write-Host "--- processes (node / electron) ---"
  Get-Process node, electron -ErrorAction SilentlyContinue |
    Where-Object { $_.Id -ne $PID } |
    Sort-Object Id |
    Format-Table Id, ProcessName, CPU -AutoSize

  foreach ($path in @($stdoutLog, $stderrLog)) {
    if (-not (Test-Path $path)) { continue }
    Write-Host "--- tail 200: $path ---"
    try {
      Get-Content $path -Tail 200 -ErrorAction Stop
    } catch {
      Write-Host "Could not tail log: $($_.Exception.Message)"
    }
    Write-Host "--- Select-String offline-kill: $path ---"
    Select-String -Path $path -Pattern "offline-kill" -SimpleMatch -ErrorAction SilentlyContinue | Select-Object -First 80
  }
}

function Stop-VerifyUiProcessTree {
  param([System.Diagnostics.Process]$Root)
  if ($null -eq $Root) { return }
  try {
    & taskkill.exe /PID $Root.Id /T /F 2>$null | Out-Null
  } catch { }
  try {
    if (-not $Root.HasExited) { $Root.Kill($true) }
  } catch { }
}

function Stop-OrphanBrowserRuntimes {
  Get-Process node, electron -ErrorAction SilentlyContinue |
    Where-Object { $_.Id -ne $PID } |
    ForEach-Object {
      try { Stop-Process -Id $_.Id -Force -ErrorAction Stop } catch { }
    }
}

$exitCode = 1
$proc = $null
$timedOut = $false

try {
  Write-Host "verify-ui-serial-worker-started=true"
  $inner = "npx playwright test e2e/react-core.spec.js e2e/agentInstall.spec.js e2e/provGraph.spec.js e2e/voiceRoom.spec.js -c playwright.e2e.config.js --workers=1"
  $cmdBody = "$inner > `"$stdoutLog`" 2> `"$stderrLog`""
  $proc = Start-Process -FilePath "cmd.exe" -ArgumentList @("/c", $cmdBody) -WorkingDirectory $repoRoot -PassThru -NoNewWindow

  if (-not $proc.WaitForExit($timeoutMs)) {
    $timedOut = $true
    Write-Host "verify-ui-serial-worker-timeout=true"
    Stop-VerifyUiProcessTree -Root $proc
    Start-Sleep -Seconds 2
    Stop-OrphanBrowserRuntimes
    Write-Diagnostics -Reason "timeout"
    $exitCode = 124
  } else {
    $exitCode = $proc.ExitCode
    if ($null -eq $exitCode) { $exitCode = 1 }
  }
} catch {
  Write-Host "verify-ui-serial-worker-error=$($_.Exception.Message)"
  $exitCode = 1
  if ($null -ne $proc) { Stop-VerifyUiProcessTree -Root $proc }
  Write-Diagnostics -Reason "exception"
} finally {
  $destDir = Join-Path $repoRoot "test-results"
  New-Item -ItemType Directory -Force -Path $destDir | Out-Null
  foreach ($pair in @(
      @($stdoutLog, "verify-ui-serial-worker.stdout.log"),
      @($stderrLog, "verify-ui-serial-worker.stderr.log")
    )) {
    $src, $name = $pair
    if (Test-Path $src) {
      Copy-Item $src (Join-Path $destDir $name) -Force -ErrorAction SilentlyContinue
    }
  }

  Write-Host "verify-ui-serial-worker-finished=true"
  Write-Host "verify-ui-serial-worker-exit-code=$exitCode"
  if ($timedOut) {
    Write-Host "verify-ui-serial-worker-timeout=true"
  }
}

exit $exitCode

