run: |
  function Test-IsOfflineKillErrorContext {
    param([System.IO.FileInfo]$f)
    if ($f.Name -ne "error-context.md") { return $false }
    $p = $f.FullName
    if ($p -like "*local-only-bridge-posture*") { return $true }
    if ($p -like "*offline-kill*") { return $true }
    if (($p -like "*react-core*") -and ($p -like "*local-only*")) { return $true }
    return $false
  }

  function Test-SkipGenericDiagnosticPrint {
    param([System.IO.FileInfo]$f)
    if (Test-IsOfflineKillErrorContext $f) { return $true }
    if ($f.Name -eq "verify-ui-serial-worker.stdout.log") { return $true }
    return $false
  }

  Write-Host "=== Verify UI offline-kill deep diagnostics (log-only) ==="
  Write-Host "verify-ui-offline-kill-error-context-start"
  if (-not (Test-Path -LiteralPath "test-results")) {
    Write-Host "verify-ui-offline-kill-error-context-no-test-results-dir=true"
  } else {
    $ecFiles = @(Get-ChildItem -LiteralPath "test-results" -Recurse -File -Filter "error-context.md" -ErrorAction SilentlyContinue | Where-Object { Test-IsOfflineKillErrorContext $_ })
    if ($ecFiles.Count -eq 0) {
      Write-Host "verify-ui-offline-kill-error-context-no-matching-files=true"
    }
    foreach ($f in $ecFiles) {
      Write-Host ""
      Write-Host "===== OFFLINE-KILL ERROR-CONTEXT: $($f.FullName) ====="
      try {
        $lines = @(Get-Content -LiteralPath $f.FullName -ErrorAction Stop)
        $n = $lines.Count
        Write-Host "verify-ui-offline-kill-error-context-line-count=$n path=$($f.FullName)"
        Write-Host "--- first 120 ---"
        $lines | Select-Object -First 120 | ForEach-Object { Write-Host $_ }
        Write-Host "verify-ui-offline-kill-error-context-tail-start path=$($f.FullName)"
        Write-Host "--- last 300 ---"
        $lines | Select-Object -Last 300 | ForEach-Object { Write-Host $_ }
      } catch {
        Write-Host "Could not read error-context: $($_.Exception.Message)"
      }
      Write-Host "===== END OFFLINE-KILL ERROR-CONTEXT ====="
    }
  }

  Write-Host "verify-ui-offline-kill-worker-stdout-tail-start"
