                    return 'offline-kill-go-offline-control-resolve-unknown-stall';
                }
                const controlResolveStallByStartStage = {
                    'offline-kill-force-posture-go-offline-control-locator-start':
                        'offline-kill-go-offline-control-locator-stalled',
                    'offline-kill-force-posture-go-offline-control-visible-wait-start':
                        'offline-kill-go-offline-control-visible-wait-stalled',
                    'offline-kill-force-posture-go-offline-control-enabled-wait-start':
                        'offline-kill-go-offline-control-enabled-wait-stalled',
                    'offline-kill-force-posture-go-offline-control-scroll-start':
                        'offline-kill-go-offline-control-scroll-stalled',
                    'offline-kill-force-posture-go-offline-control-compact-before-start':
                        'offline-kill-go-offline-control-compact-before-stalled',
                    'offline-kill-force-posture-go-offline-control-attach-before-start':
                        'offline-kill-go-offline-control-attach-before-stalled',
                };
                if (controlResolveStallByStartStage[lastFp]) return controlResolveStallByStartStage[lastFp];
                return 'offline-kill-go-offline-control-resolve-unknown-stall';
