async function collectGoOfflineControlVisibleWaitProbeBestEffort(pg = page) {
    if (pg.isClosed()) {
        return { probeError: 'page-closed' };
    }
    try {
        const dom = await pg.evaluate(() => {
            const pickText = (el) => (el && el.textContent ? el.textContent.trim().slice(0, 200) : '');
            const domGeomVis = (el) => {
                if (!(el instanceof Element)) return false;
                const r = el.getBoundingClientRect();
                const st = window.getComputedStyle(el);
                return (
                    r.width > 0 &&
                    r.height > 0 &&
                    st.display !== 'none' &&
                    st.visibility !== 'hidden' &&
                    Number(st.opacity || '1') > 0
                );
            };
            const testidPath = (el) => {
                const parts = [];
                let cur = el;
                for (let i = 0; i < 14 && cur && cur instanceof Element; i++, cur = cur.parentElement) {
                    const tid = cur.getAttribute?.('data-testid');
                    if (tid) parts.push(tid);
                }
                return parts.join('<');
            };
            const scopedSel =
                '[data-testid="settings-drawer"][data-state="open"] [data-testid="settings-offline-kill-btn"]';
            const scopedList = Array.from(document.querySelectorAll(scopedSel));
            const globalList = Array.from(document.querySelectorAll('[data-testid="settings-offline-kill-btn"]'));

            const describeEl = (el, rule) => {
                if (!(el instanceof Element)) return null;
                const r = el.getBoundingClientRect();
                const st = window.getComputedStyle(el);
                const role = el.getAttribute?.('role') || '';
                return {
                    rule,
                    tagName: String(el.tagName || ''),
                    dataTestId: el.getAttribute?.('data-testid') || '',
                    role,
                    text: pickText(el),
                    ariaLabel: (el.getAttribute?.('aria-label') || '').slice(0, 200),
                    disabled: Boolean(el.disabled),
                    domGeometryVisible: domGeomVis(el),
                    bbox: {
                        x: Math.round(r.x),
                        y: Math.round(r.y),
                        w: Math.round(r.width),
                        h: Math.round(r.height),
                    },
                    display: st.display,
                    visibility: st.visibility,
                    opacity: st.opacity,
                    testidPath: testidPath(el),
                };
            };

            const drawer = document.querySelector('[data-testid="settings-drawer"]');
            const connTab = document.querySelector('[data-testid="settings-tab-connection"]');
            const connPanel = document.querySelector('[data-testid="settings-panel-connection"]');
            const controls = document.querySelector('[data-testid="settings-connection-controls"]');

            const candidateSet = new Map();
            const addEl = (el, rule) => {
                if (!(el instanceof Element)) return;
                if (candidateSet.size >= 48) return;
                if (candidateSet.has(el)) return;
                candidateSet.set(el, rule);
            };

            document.querySelectorAll('[data-testid*="offline"]').forEach((el) => addEl(el, 'testid*offline'));
            document.querySelectorAll('[data-testid*="kill"]').forEach((el) => addEl(el, 'testid*kill'));
            document.querySelectorAll('[data-testid*="local"]').forEach((el) => addEl(el, 'testid*local'));

            Array.from(document.querySelectorAll('button')).forEach((el) => {
                const t = pickText(el).toLowerCase();
                if (/(go\s+offline|^offline\b|local\s+only|kill\s+switch)/i.test(t)) addEl(el, 'button-text');
            });

            document.querySelectorAll('input[type="checkbox"],[role="switch"],[role="checkbox"]').forEach((el) => {
                const lab = `${el.getAttribute?.('aria-label') || ''} ${pickText(el)}`;
                if (/offline|kill|local|go\s+offline/i.test(lab)) addEl(el, 'input-switch-label');
            });

