function refineOfflineKillGoOfflineVisibleWaitClassification(base, goState, probe) {
    if (base !== 'offline-kill-go-offline-control-visible-wait-stalled') return base;
    if (!probe || probe.probeError) return base;
    const pw = probe.playwright && typeof probe.playwright === 'object' ? probe.playwright : {};
    const gc = Math.max(Number(probe.globalCanonicalCount || 0), Number(pw.globalCount || 0));
    const sc = Math.max(Number(probe.scopedCanonicalCount || 0), Number(pw.scopedCount || 0));
    const cand = Array.isArray(probe.candidates) ? probe.candidates : [];
    const scopedPv = Boolean(pw.scopedFirstVisible);
    const globalPv = Boolean(pw.globalFirstVisible);
    const ps = probe.primaryScopedCanonical;
    const pg = probe.primaryGlobalCanonical;
    const drawerState = String(probe.drawer?.dataState || '');
    const tabActive = String(probe.connectionTab?.dataActive || '');

    if (gc === 0 && sc === 0) {
        if (cand.length > 0) return 'offline-kill-go-offline-control-selector-mismatch';
        return 'offline-kill-go-offline-control-selector-missing';
    }

    if (sc >= 1 && ps) {
        if (ps.domGeometryVisible && !scopedPv) {
            return 'offline-kill-go-offline-control-present-dom-visible-playwright-hidden';
        }
        if (!ps.domGeometryVisible) {
            return 'offline-kill-go-offline-control-present-hidden';
        }
    }

    if (gc >= 1 && sc === 0) {
        if (drawerState !== 'open') return 'offline-kill-go-offline-wrong-panel-or-tab';
        if (tabActive !== 'true') return 'offline-kill-go-offline-wrong-panel-or-tab';
        if (goState && goState.connectionPanelVisible === false) {
            return 'offline-kill-go-offline-wrong-panel-or-tab';
        }
        if (pg && pg.domGeometryVisible && !globalPv) {
            return 'offline-kill-go-offline-control-present-dom-visible-playwright-hidden';
        }
        if (pg && !pg.domGeometryVisible) {
            return 'offline-kill-go-offline-control-present-hidden';
        }
        return 'offline-kill-go-offline-wrong-panel-or-tab';
    }

    if (gc >= 1 && sc >= 1 && ps && ps.domGeometryVisible && !scopedPv) {
        return 'offline-kill-go-offline-control-present-dom-visible-playwright-hidden';
    }

    return base;
}

