/**
 * DOM + hit-test snapshot for Go Offline kill button immediately before Playwright click (harness-only).
 */
async function collectGoOfflineKillButtonActionabilitySnapshot(locator) {
    try {
        return await locator.evaluate((el) => {
            if (!(el instanceof HTMLElement)) {
                return { ok: false, reason: 'not-html-element' };
            }
            const r = el.getBoundingClientRect();
            const cx = r.left + Math.max(1, r.width / 2);
            const cy = r.top + Math.max(1, r.height / 2);
            const top = document.elementFromPoint(cx, cy);
            const cs = window.getComputedStyle(el);
            const disabledAttr = Boolean(
                (el instanceof HTMLButtonElement || el instanceof HTMLInputElement || el instanceof HTMLSelectElement) &&
                    el.disabled,
            );
            const ariaDis = el.getAttribute('aria-disabled') === 'true';
            const inertAncestor = Boolean(el.closest('[inert]'));
            return {
                ok: true,
                disabledAttr,
                ariaDisabledTrue: ariaDis,
                pointerEvents: String(cs.pointerEvents || ''),
                opacity: String(cs.opacity || ''),
                inertAncestor,
                bbox: {
                    x: Math.round(r.x),
                    y: Math.round(r.y),
                    width: Math.round(r.width),
                    height: Math.round(r.height),
                },
                center: { cx: Math.round(cx), cy: Math.round(cy) },
                centerElementTag: top ? String(top.tagName || '') : '',
                centerElementTestId: top && top.getAttribute ? top.getAttribute('data-testid') || '' : '',
                centerHitIsKillOrDescendant: !!(top && (top === el || el.contains(top))),
            };
        });
    } catch (e) {
        return { ok: false, evaluateError: e?.message || String(e) };
    }
}

