            .evaluate((btn) => {
                try {
                    if (!(btn instanceof HTMLElement)) {
                        return {
                            collectError: 'not-htmlelement',
                            settingsOpenBtnCount: 0,
                            attached: false,
                            visible: false,
                        };
                    }
                    const cnt = document.querySelectorAll('[data-testid="settings-open-btn"]').length;
                    return {
                        collectError: null,
                        settingsOpenBtnCount: cnt,
                        attached: btn.isConnected,
                    };
                } catch (err) {
                    return { collectError: err && err.message ? String(err.message) : String(err), settingsOpenBtnCount: -1 };
                }
            })
            .catch((e) => ({ collectError: e && e.message ? String(e.message) : String(e), settingsOpenBtnCount: -1 })),
    );

    const resolvePart = await runSeg('first-click-target-resolve', 'firstClickTargetResolveDone', async () => {
        const h = await btnLocator.elementHandle();
        try {
            await h.evaluate((btn) => (btn && btn.isConnected ? 1 : 0));
        } finally {
            await h.dispose().catch(() => {});
        }
        return {};
    });

    const bboxPart = await runSeg('first-click-target-bbox', 'firstClickTargetBboxDone', () =>
        btnLocator
            .evaluate((btn) => {
                try {
                    if (!(btn instanceof HTMLElement)) {
                        return { collectError: 'not-htmlelement-bbox' };
                    }
                    const r = btn.getBoundingClientRect();
                    const st = window.getComputedStyle(btn);
                    const rectVisible = () =>
                        r.width > 0 &&
                        r.height > 0 &&
                        st.visibility !== 'hidden' &&
                        st.display !== 'none' &&
                        Number(st.opacity || '1') > 0;
                    return {
                        collectError: null,
                        visible: rectVisible(),
                        disabled: Boolean(btn.disabled),
                        ariaDisabled: btn.getAttribute('aria-disabled'),
                        boundingBox: { x: r.x, y: r.y, width: r.width, height: r.height },
                        pointerEvents: st.pointerEvents,
                        opacity: st.opacity,
                        zIndex: st.zIndex,
                    };
                } catch (err) {
                    return { collectError: err && err.message ? String(err.message) : String(err) };
                }
            })
            .catch((e) => ({ collectError: e && e.message ? String(e.message) : String(e) })),
    );

    const efpPart = await runSeg('first-click-target-elementfrompoint', 'firstClickTargetElementFromPointDone', () =>
        btnLocator
            .evaluate((btn) => {
                try {
                    if (!(btn instanceof HTMLElement)) {
                        return { collectError: 'not-htmlelement-efp', settingsOpenBtnCount: -1 };
                    }
                    const r = btn.getBoundingClientRect();
                    const st = window.getComputedStyle(btn);
                    const cx = r.left + Math.min(Math.max(r.width / 2, 1), r.width);
                    const cy = r.top + Math.min(Math.max(r.height / 2, 1), r.height);
                    const ep = document.elementFromPoint(cx, cy);
                    const overlayCandidates = [];
                    document.querySelectorAll('[aria-modal="true"], [role="dialog"]').forEach((el) => {
                        if (!(el instanceof HTMLElement) || el === btn || el.contains(btn)) return;
                        const er = el.getBoundingClientRect();
                        if (cx >= er.left && cx <= er.right && cy >= er.top && cy <= er.bottom) {
                            overlayCandidates.push({
                                tag: el.tagName,
                                dataTestId: el.getAttribute('data-testid') || '',
                                role: el.getAttribute('role') || '',
                                ariaModal: el.getAttribute('aria-modal') || '',
                            });
                        }
                    });
