                    const cnt = document.querySelectorAll('[data-testid="settings-open-btn"]').length;
                    const openerHit =
                        ep &&
                        (ep === btn ||
                            (typeof btn.contains === 'function' && btn.contains(ep)) ||
                            (typeof ep.contains === 'function' && ep.contains(btn)));
                    return {
                        collectError: null,
                        settingsOpenBtnCount: cnt,
                        activeElement:
                            ae instanceof Element
                                ? { tag: ae.tagName, dataTestId: ae.getAttribute('data-testid') || '' }
                                : null,
                        elementFromPointAtCenter: ep
                            ? {
                                  tag: ep.tagName,
                                  dataTestId: ep.getAttribute('data-testid') || '',
                                  id: ep.id || '',
                                  className: String(ep.className || '').slice(0, 160),
                                  isSettingsOpener: Boolean(openerHit),
                              }
                            : null,
                        overlayCandidatesAtCenter: overlayCandidates.slice(0, 14),
                        drawerCount: document.querySelectorAll('[data-testid="settings-drawer"]').length,
                        openDrawerCount: document.querySelectorAll('[data-testid="settings-drawer"][data-state="open"]').length,
                    };
                } catch (err) {
                    return { collectError: err && err.message ? String(err.message) : String(err), settingsOpenBtnCount: -1 };
                }
            })
            .catch((e) => ({ collectError: e && e.message ? String(e.message) : String(e), settingsOpenBtnCount: -1 })),
    );

    const probePart = await runSeg('first-click-target-probe-install', 'firstClickTargetProbeInstallDone', async () => {
        await installOfflineKillFirstClickCommitProbe(pg).catch(() => {});
        return {};
    });

