function classifyOfflineKillEnsurePanelAfterProviderTimeout(st, lastEpRaw) {
    const stSafe = st && typeof st === 'object' ? st : {};
    const lastEp = String(lastEpRaw || '');
    if (stSafe.pageClosed) return 'offline-kill-ensure-panel-after-provider-page-closed';
    if (!stSafe.settingsDrawerPresent) return 'offline-kill-ensure-panel-drawer-missing';
    if (!stSafe.settingsDrawerVisible) return 'offline-kill-ensure-panel-drawer-not-ready';
    if (stSafe.loadingShellPresent) return 'offline-kill-ensure-panel-drawer-not-ready';
    const drawerReadyBad =
        stSafe.settingsDrawerReady === false ||
        stSafe.settingsDrawerDataReady === 'false' ||
        stSafe.drawerDataReady === 'false';
    if (drawerReadyBad) return 'offline-kill-ensure-panel-drawer-not-ready';
    const tab = String(stSafe.activeSettingsTab || 'unknown');
    if (tab !== 'connection' && tab !== 'unknown') {
        return 'offline-kill-ensure-panel-wrong-tab';
    }
    if (!stSafe.connectionPanelPresent) {
        return 'offline-kill-ensure-panel-connection-panel-missing';
    }
    if (!stSafe.connectionPanelVisible) {
        return 'offline-kill-ensure-panel-connection-panel-hidden';
    }
    const hasCtrl =
        stSafe.providerControlPresent === true ||
        (Number.isFinite(Number(stSafe.providerControlCount)) && Number(stSafe.providerControlCount) > 0);
    if (!hasCtrl) {
        return 'offline-kill-ensure-panel-provider-control-missing';
    }
    if (!stSafe.providerControlVisible) {
        return 'offline-kill-ensure-panel-provider-control-hidden';
    }
    if (
        stSafe.providerControlEnabled === false ||
        stSafe.providerControlDisabledAttr === true ||
        stSafe.providerControlAriaDisabled === 'true'
    ) {
        return 'offline-kill-ensure-panel-provider-control-disabled';
    }
    const sel = String(stSafe.selectedProvider || '').trim();
    if (sel && sel !== 'openrouter') {
        return 'offline-kill-ensure-panel-provider-value-not-openrouter';
    }
    if (lastEp === 'offline-kill-force-posture-ensure-panel-provider-value-start') {
        return 'offline-kill-ensure-panel-provider-value-wait-stalled';
    }
    if (lastEp === 'offline-kill-force-posture-ensure-panel-drawer-resolve-start') {
        return 'offline-kill-ensure-panel-drawer-not-ready';
    }
    if (lastEp === 'offline-kill-force-posture-ensure-panel-drawer-ready-start') {
        return 'offline-kill-ensure-panel-drawer-not-ready';
    }
    if (lastEp === 'offline-kill-force-posture-ensure-panel-connection-tab-start') {
        return 'offline-kill-ensure-panel-wrong-tab';
    }
    if (lastEp === 'offline-kill-force-posture-ensure-panel-connection-panel-visible-start') {
        if (!stSafe.connectionPanelPresent) return 'offline-kill-ensure-panel-connection-panel-missing';
        if (!stSafe.connectionPanelVisible) return 'offline-kill-ensure-panel-connection-panel-hidden';
        return 'offline-kill-ensure-panel-connection-panel-hidden';
    }
    return 'offline-kill-ensure-panel-unknown-timeout';
}

