/**
 * OpenRouter provider-select harness: same locator Playwright uses vs scoped `querySelector`,
 * plus native `<select>` shape/value/option facts (merged into poll-timeout artifacts).
 */
async function captureOpenrouterProviderSelectHarness(pg, providerLoc) {
    const out = {};
    try {
        const pageProbe = await pg.evaluate(() => {
            const sel = '[data-testid="settings-connection-controls"] [data-testid="settings-provider-select"]';
            const all = document.querySelectorAll('[data-testid="settings-provider-select"]');
            const scoped = document.querySelector(sel);
            return {
                providerSelectCount: all.length,
                providerSelectScopedQueryExists: Boolean(scoped),
                providerSelectScopedQueryValue: scoped && 'value' in scoped ? String(scoped.value || '') : '',
                providerSelectScopedQueryTagName: scoped && scoped.tagName ? String(scoped.tagName) : '',
            };
        });
        Object.assign(out, pageProbe);
    } catch (err) {
        out.providerSelectPageProbeError = err?.message || String(err);
    }
    try {
        const elProbe = await providerLoc.evaluate((el) => {
            const o = {
                openrouterSelectTagName: el && el.tagName ? String(el.tagName) : '',
                openrouterSelectIsNativeSelect: el instanceof HTMLSelectElement,
                openrouterSelectConnected: el instanceof Node ? el.isConnected : false,
                openrouterSelectDisabled: el instanceof HTMLElement ? Boolean(el.disabled) : false,
                openrouterSelectSelectedIndex: el instanceof HTMLSelectElement ? el.selectedIndex : null,
                openrouterSelectValueCurrent: el && 'value' in el ? String(el.value || '') : '',
                openrouterSelectOptionValues: [],
                openrouterOptionExists: false,
                openrouterOptionDisabled: false,
                providerSelectLocatorMatchesQuerySelector: false,
                providerSelectQuerySelectorMiss: false,
            };
            const scoped = document.querySelector(
                '[data-testid="settings-connection-controls"] [data-testid="settings-provider-select"]',
            );
            o.providerSelectQuerySelectorMiss = !scoped;
            o.providerSelectLocatorMatchesQuerySelector = Boolean(scoped && el === scoped);
            if (!(el instanceof HTMLSelectElement)) return o;
            o.openrouterSelectOptionValues = Array.from(el.options)
                .slice(0, 48)
                .map((v) => String(v.value || '').slice(0, 96));
            const opt = Array.from(el.options).find((x) => String(x.value) === 'openrouter');
            o.openrouterOptionExists = Boolean(opt);
            o.openrouterOptionDisabled = opt ? Boolean(opt.disabled) : false;
            return o;
        });
        Object.assign(out, elProbe);
    } catch (err) {
        out.providerSelectLocatorProbeError = err?.message || String(err);
    }
    const stable = out.providerSelectLocatorMatchesQuerySelector ? 'locator-matches-scoped-query' : 'locator-differs-scoped-query';
    out.providerSelectStableNodeLabel = stable;
    return out;
}

function classifyProviderSelectOpenrouterPollHarness(innerPc, helperStage, harness, orState) {
    const h = harness && typeof harness === 'object' ? harness : {};
    const pc = String(innerPc || '').trim();
    const hs = String(helperStage || '').trim();
    const pollish = pc === 'provider-select-poll-timeout' || (pc === 'provider-select-helper-timeout' && hs === 'poll');
    if (!pollish) return null;
    if (h.providerSelectRemountedDuringFallback === true) {
        return 'provider-select-control-remounted-during-fallback';
    }
    if (h.openrouterSelectIsNativeSelect === false) {
        return 'provider-select-not-native-select-during-fallback';
    }
    if (h.openrouterOptionExistsDuringFallback === false) {
        return 'provider-select-openrouter-option-missing-during-fallback';
    }
    if (h.openrouterOptionDisabledDuringFallback === true) {
        return 'provider-select-openrouter-option-disabled-during-fallback';
    }
    if (h.openrouterSelectReactResetAfterFallback === true) {
        return 'provider-select-react-reset-value-after-fallback';
    }
    const imm = String(h.openrouterSelectValueImmediatelyAfterSet || '');
    const aftEv = String(h.openrouterSelectValueAfterInputChangeEvents || '');
    if (imm === 'openrouter' && aftEv !== 'openrouter') {
        return 'provider-select-react-reset-value-after-fallback';
    }
    const readAfter = String(h.openrouterSelectValueAfterReadAfterSelect || '').trim();
    if (readAfter === '' && h.nativeFallbackRan === true) {
        return 'provider-select-value-empty-after-fallback';
    }
    const st = orState && typeof orState === 'object' ? orState : {};
    const sel = String(st.selectedProvider || '').trim();
    const pv = String(st.providerControlValue || '').trim();
    if (readAfter === '' && sel === '' && pv === '') {
        return 'provider-select-value-empty-after-fallback';
    }
    return 'provider-select-poll-timeout-value-empty';
}

